// Auto-generated fallback HTML templates embedded directly to ensure zero external file dependency
export const BUILTIN_UPLOAD_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>File Drop Portal - OpenClaw</title>\n    <style>\n        :root {\n            --bg-color: #090d13;\n            --surface-card: #131923;\n            --surface-elevated: #1a2230;\n            --border: #242f42;\n            --border-hover: #3b4d6b;\n            --text-primary: #e6edf3;\n            --text-secondary: #8b9bb4;\n            --accent-color: #58a6ff;\n            --accent-hover: #388bfd;\n            --accent-glow: rgba(88, 166, 255, 0.15);\n            --success-color: #3fb950;\n            --danger-color: #f85149;\n            --font-stack: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;\n            --font-mono: ui-monospace, SFMono-Regular, \"SF Mono\", Menlo, Consolas, monospace;\n        }\n        * { box-sizing: border-box; margin: 0; padding: 0; }\n        body {\n            background-color: var(--bg-color);\n            color: var(--text-primary);\n            font-family: var(--font-stack);\n            min-height: 100vh;\n            display: flex;\n            flex-direction: column;\n            align-items: center;\n            padding: 32px 16px;\n        }\n        .container {\n            width: 100%;\n            max-width: 680px;\n        }\n        .header {\n            margin-bottom: 24px;\n            text-align: center;\n        }\n        .header h1 {\n            font-size: 24px;\n            font-weight: 600;\n            letter-spacing: -0.5px;\n            margin-bottom: 8px;\n            color: #f0f6fc;\n        }\n        .header p {\n            color: var(--text-secondary);\n            font-size: 14px;\n        }\n        .card {\n            background-color: var(--surface-card);\n            border: 1px solid var(--border);\n            border-radius: 12px;\n            padding: 24px;\n            margin-bottom: 20px;\n            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.4);\n        }\n        .channel-info {\n            display: grid;\n            grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));\n            gap: 16px;\n            margin-bottom: 24px;\n            padding-bottom: 20px;\n            border-bottom: 1px solid var(--border);\n        }\n        .info-item {\n            display: flex;\n            flex-direction: column;\n            gap: 4px;\n        }\n        .info-label {\n            font-size: 11px;\n            text-transform: uppercase;\n            letter-spacing: 0.8px;\n            color: var(--text-secondary);\n        }\n        .info-value {\n            font-size: 14px;\n            font-weight: 600;\n            color: var(--text-primary);\n            font-family: var(--font-mono);\n        }\n        .badge {\n            display: inline-block;\n            background: rgba(88, 166, 255, 0.12);\n            color: var(--accent-color);\n            padding: 2px 8px;\n            border-radius: 4px;\n            font-size: 12px;\n            width: fit-content;\n        }\n        .dropzone {\n            border: 2px dashed var(--border);\n            border-radius: 10px;\n            padding: 40px 20px;\n            text-align: center;\n            cursor: pointer;\n            transition: all 0.2s ease;\n            background: rgba(19, 25, 35, 0.5);\n        }\n        .dropzone:hover, .dropzone.dragover {\n            border-color: var(--accent-color);\n            background: var(--accent-glow);\n        }\n        .dropzone-icon {\n            font-size: 36px;\n            margin-bottom: 12px;\n            color: var(--accent-color);\n        }\n        .dropzone-title {\n            font-size: 16px;\n            font-weight: 500;\n            margin-bottom: 6px;\n        }\n        .dropzone-hint {\n            font-size: 13px;\n            color: var(--text-secondary);\n        }\n        #file-input { display: none; }\n        .upload-queue {\n            margin-top: 20px;\n            display: flex;\n            flex-direction: column;\n            gap: 12px;\n        }\n        .queue-item {\n            background-color: var(--surface-elevated);\n            border: 1px solid var(--border);\n            border-radius: 8px;\n            padding: 12px 16px;\n            display: flex;\n            flex-direction: column;\n            gap: 8px;\n        }\n        .queue-item-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            font-size: 14px;\n        }\n        .queue-filename {\n            font-weight: 500;\n            max-width: 75%;\n            overflow: hidden;\n            text-overflow: ellipsis;\n            white-space: nowrap;\n        }\n        .queue-filesize {\n            color: var(--text-secondary);\n            font-size: 12px;\n            font-family: var(--font-mono);\n        }\n        .progress-bar-wrap {\n            height: 6px;\n            background-color: var(--border);\n            border-radius: 3px;\n            overflow: hidden;\n        }\n        .progress-bar-fill {\n            height: 100%;\n            background-color: var(--accent-color);\n            width: 0%;\n            transition: width 0.15s ease;\n        }\n        .queue-status {\n            font-size: 12px;\n            color: var(--text-secondary);\n            display: flex;\n            justify-content: space-between;\n        }\n        .status-success { color: var(--success-color); }\n        .status-error { color: var(--danger-color); }\n        .btn-submit {\n            margin-top: 20px;\n            width: 100%;\n            padding: 12px;\n            background-color: var(--accent-color);\n            color: #fff;\n            border: none;\n            border-radius: 8px;\n            font-size: 14px;\n            font-weight: 600;\n            cursor: pointer;\n            transition: background 0.2s ease;\n        }\n        .btn-submit:hover:not(:disabled) {\n            background-color: var(--accent-hover);\n        }\n        .btn-submit:disabled {\n            opacity: 0.5;\n            cursor: not-allowed;\n        }\n        .btn-sm {\n            padding: 4px 10px;\n            font-size: 12px;\n            background-color: var(--surface-elevated);\n            border: 1px solid var(--border);\n            color: var(--text-primary);\n            border-radius: 6px;\n            cursor: pointer;\n            text-decoration: none;\n            transition: all 0.2s;\n        }\n        .btn-sm:hover {\n            border-color: var(--border-hover);\n            color: var(--accent-color);\n        }\n        .section-title {\n            font-size: 14px;\n            font-weight: 600;\n            margin-bottom: 16px;\n            color: #f0f6fc;\n            letter-spacing: -0.2px;\n        }\n        .history-list {\n            display: flex;\n            flex-direction: column;\n            gap: 10px;\n        }\n        .history-item {\n            background-color: var(--surface-elevated);\n            border: 1px solid var(--border);\n            border-radius: 8px;\n            padding: 10px 14px;\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n        }\n        .file-name {\n            font-size: 13px;\n            font-family: var(--font-mono);\n            overflow: hidden;\n            text-overflow: ellipsis;\n            white-space: nowrap;\n            max-width: 60%;\n        }\n        .file-meta {\n            font-size: 12px;\n            color: var(--text-secondary);\n        }\n        .empty-state {\n            text-align: center;\n            padding: 24px 0;\n            color: var(--text-secondary);\n            font-size: 13px;\n        }\n        .footer-note {\n            text-align: center;\n            font-size: 12px;\n            color: var(--text-secondary);\n            margin-top: 16px;\n        }\n    </style>\n</head>\n<body>\n    <div class=\"container\">\n        <div class=\"header\">\n            <h1>OpenClaw File Drop Portal</h1>\n            <p>Upload files directly to the workspace through a secure channel</p>\n        </div>\n\n        <div class=\"card\">\n            <div class=\"channel-info\">\n                <div class=\"info-item\">\n                    <span class=\"info-label\">Channel Code</span>\n                    <div style=\"display:flex;align-items:center;gap:6px;\">\n                        <span class=\"info-value badge\">{{.Code}}</span>\n                        <button type=\"button\" class=\"btn-sm\" id=\"btn-copy-link\" onclick=\"copyLink()\">Copy Link</button>\n                    </div>\n                </div>\n                <div class=\"info-item\">\n                    <span class=\"info-label\">Active Host</span>\n                    <span class=\"info-value\" id=\"current-host\" style=\"font-size:12px;color:var(--text-secondary);\">Detecting...</span>\n                </div>\n                <div class=\"info-item\">\n                    <span class=\"info-label\">Expires In</span>\n                    <span class=\"info-value\" id=\"countdown\">Calculating...</span>\n                </div>\n                <div class=\"info-item\">\n                    <span class=\"info-label\">Target Directory</span>\n                    <span class=\"info-value\">{{.RelDir}}</span>\n                </div>\n                <div class=\"info-item\">\n                    <span class=\"info-label\">Upload Limit</span>\n                    <span class=\"info-value\">{{.LimitDesc}}</span>\n                </div>\n            </div>\n\n            <div class=\"dropzone\" id=\"dropzone\">\n                <div class=\"dropzone-icon\">⇪</div>\n                <div class=\"dropzone-title\">Drag & drop files here, or click to browse</div>\n                <div class=\"dropzone-hint\">Max {{.MaxSizeDesc}} per request · Multiple files supported</div>\n                <input type=\"file\" id=\"file-input\" multiple>\n            </div>\n\n            <div class=\"upload-queue\" id=\"queue-container\"></div>\n            <button class=\"btn-submit\" id=\"btn-upload\" style=\"display:none;\" disabled>Start Upload</button>\n        </div>\n\n        <div class=\"card\">\n            <div class=\"section-title\">Received Files</div>\n            {{if .Files}}\n            <div class=\"history-list\" id=\"history-list\">\n                {{range .Files}}\n                <div class=\"history-item\">\n                    <span class=\"file-name\" title=\"{{.Filename}}\">{{.Filename}}</span>\n                    <div style=\"display:flex;align-items:center;gap:10px;\">\n                        <span class=\"file-meta\">{{.SizeStr}} · {{.TimeStr}}</span>\n                        <a href=\"/d/{{$.Code}}/{{.Filename}}\" target=\"_blank\" class=\"btn-sm\">Download</a>\n                    </div>\n                </div>\n                {{end}}\n            </div>\n            {{else}}\n            <div class=\"empty-state\" id=\"empty-state\">No uploaded files yet</div>\n            {{end}}\n        </div>\n\n        <div class=\"footer-note\">\n            End-to-End Streaming · SHA-256 Audit · Physical Sandbox Isolation\n        </div>\n    </div>\n\n    <script>\n        (function() {\n            const currentHostEl = document.getElementById('current-host');\n            if (currentHostEl) {\n                currentHostEl.innerText = window.location.host;\n            }\n\n            window.copyLink = function() {\n                const btn = document.getElementById('btn-copy-link');\n                navigator.clipboard.writeText(window.location.href).then(() => {\n                    btn.innerText = 'Copied!';\n                    setTimeout(() => btn.innerText = 'Copy Link', 2000);\n                }).catch(() => {\n                    prompt('Copy portal link:', window.location.href);\n                });\n            };\n\n            let remaining = {{.RemainingSeconds}};\n            const countdownEl = document.getElementById('countdown');\n            function updateCountdown() {\n                if (remaining <= 0) {\n                    countdownEl.innerText = \"Expired\";\n                    countdownEl.style.color = \"var(--danger-color)\";\n                    return;\n                }\n                const h = Math.floor(remaining / 3600);\n                const m = Math.floor((remaining % 3600) / 60);\n                const s = remaining % 60;\n                countdownEl.innerText = (h > 0 ? h + 'h ' : '') + m + 'm ' + s + 's';\n                remaining--;\n            }\n            updateCountdown();\n            setInterval(updateCountdown, 1000);\n\n            const dropzone = document.getElementById('dropzone');\n            const fileInput = document.getElementById('file-input');\n            const queueContainer = document.getElementById('queue-container');\n            const btnUpload = document.getElementById('btn-upload');\n\n            let selectedFiles = [];\n\n            function formatBytes(bytes) {\n                if (bytes === 0) return '0 B';\n                const k = 1024;\n                const sizes = ['B', 'KB', 'MB', 'GB'];\n                const i = Math.floor(Math.log(bytes) / Math.log(k));\n                return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];\n            }\n\n            dropzone.addEventListener('click', () => fileInput.click());\n\n            ['dragenter', 'dragover'].forEach(name => {\n                dropzone.addEventListener(name, (e) => {\n                    e.preventDefault();\n                    e.stopPropagation();\n                    dropzone.classList.add('dragover');\n                });\n            });\n\n            ['dragleave', 'drop'].forEach(name => {\n                dropzone.addEventListener(name, (e) => {\n                    e.preventDefault();\n                    e.stopPropagation();\n                    dropzone.classList.remove('dragover');\n                });\n            });\n\n            dropzone.addEventListener('drop', (e) => {\n                const files = e.dataTransfer.files;\n                if (files && files.length > 0) {\n                    handleFiles(Array.from(files));\n                }\n            });\n\n            fileInput.addEventListener('change', () => {\n                if (fileInput.files && fileInput.files.length > 0) {\n                    handleFiles(Array.from(fileInput.files));\n                }\n            });\n\n            function handleFiles(files) {\n                files.forEach(f => {\n                    selectedFiles.push({ file: f, uploaded: false });\n                });\n                renderQueue();\n            }\n\n            function renderQueue() {\n                queueContainer.innerHTML = '';\n                if (selectedFiles.length === 0) {\n                    btnUpload.style.display = 'none';\n                    return;\n                }\n                btnUpload.style.display = 'block';\n                btnUpload.disabled = false;\n                btnUpload.innerText = 'Upload ' + selectedFiles.length + ' file(s)';\n\n                selectedFiles.forEach((item, idx) => {\n                    const row = document.createElement('div');\n                    row.className = 'queue-item';\n                    row.id = 'queue-item-' + idx;\n                    row.innerHTML = `\n                        <div class=\"queue-item-header\">\n                            <span class=\"queue-filename\" title=\"${escapeHtml(item.file.name)}\">${escapeHtml(item.file.name)}</span>\n                            <span class=\"queue-filesize\">${formatBytes(item.file.size)}</span>\n                        </div>\n                        <div class=\"progress-bar-wrap\">\n                            <div class=\"progress-bar-fill\" id=\"bar-${idx}\"></div>\n                        </div>\n                        <div class=\"queue-status\">\n                            <span id=\"status-${idx}\">Pending...</span>\n                            <span id=\"percent-${idx}\">0%</span>\n                        </div>\n                    `;\n                    queueContainer.appendChild(row);\n                });\n            }\n\n            function escapeHtml(str) {\n                const div = document.createElement('div');\n                div.textContent = str;\n                return div.innerHTML;\n            }\n\n            btnUpload.addEventListener('click', () => {\n                uploadNext(0);\n            });\n\n            function uploadNext(index) {\n                if (index >= selectedFiles.length) {\n                    btnUpload.disabled = true;\n                    btnUpload.innerText = 'All uploads completed';\n                    setTimeout(() => window.location.reload(), 1500);\n                    return;\n                }\n\n                const item = selectedFiles[index];\n                if (item.uploaded) {\n                    uploadNext(index + 1);\n                    return;\n                }\n\n                btnUpload.disabled = true;\n                btnUpload.innerText = 'Uploading ' + (index + 1) + '/' + selectedFiles.length + '...';\n\n                const bar = document.getElementById('bar-' + index);\n                const status = document.getElementById('status-' + index);\n                const percent = document.getElementById('percent-' + index);\n\n                status.innerText = 'Uploading...';\n\n                const xhr = new XMLHttpRequest();\n                const formData = new FormData();\n                formData.append('file', item.file);\n\n                xhr.upload.addEventListener('progress', (e) => {\n                    if (e.lengthComputable) {\n                        const p = Math.round((e.loaded / e.total) * 100);\n                        bar.style.width = p + '%';\n                        percent.innerText = p + '%';\n                    }\n                });\n\n                xhr.addEventListener('load', () => {\n                    if (xhr.status >= 200 && xhr.status < 300) {\n                        bar.style.width = '100%';\n                        bar.style.background = 'var(--success-color)';\n                        percent.innerText = '100%';\n                        status.className = 'status-success';\n                        status.innerText = 'Uploaded';\n                        item.uploaded = true;\n                        uploadNext(index + 1);\n                    } else {\n                        bar.style.background = 'var(--danger-color)';\n                        status.className = 'status-error';\n                        let errText = 'Upload failed (' + xhr.status + ')';\n                        try {\n                            const resp = JSON.parse(xhr.responseText);\n                            if (resp && resp.error) errText = resp.error;\n                        } catch(e) {}\n                        status.innerText = errText;\n                        btnUpload.disabled = false;\n                        btnUpload.innerText = 'Retry remaining';\n                    }\n                });\n\n                xhr.addEventListener('error', () => {\n                    bar.style.background = 'var(--danger-color)';\n                    status.className = 'status-error';\n                    status.innerText = 'Network error';\n                    btnUpload.disabled = false;\n                    btnUpload.innerText = 'Retry remaining';\n                });\n\n                xhr.open('POST', window.location.pathname, true);\n                xhr.send(formData);\n            }\n        })();\n    </script>\n</body>\n</html>\n";
export const BUILTIN_ERROR_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>{{.Status}} - {{.Title}}</title>\n    <style>\n        :root {\n            --bg-color: #0d1117;\n            --card-bg: #161b22;\n            --border-color: #30363d;\n            --text-primary: #c9d1d9;\n            --text-secondary: #8b949e;\n            --accent-danger: #f85149;\n            --accent-warn: #d29922;\n        }\n        * { box-sizing: border-box; margin: 0; padding: 0; }\n        body {\n            background-color: var(--bg-color);\n            color: var(--text-primary);\n            font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Helvetica, Arial, sans-serif;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            min-height: 100vh;\n            padding: 20px;\n        }\n        .card {\n            background-color: var(--card-bg);\n            border: 1px solid var(--border-color);\n            border-radius: 12px;\n            padding: 40px;\n            max-width: 480px;\n            width: 100%;\n            text-align: center;\n            box-shadow: 0 8px 24px rgba(0,0,0,0.5);\n        }\n        .status-badge {\n            display: inline-block;\n            font-size: 14px;\n            font-weight: 600;\n            padding: 4px 12px;\n            border-radius: 20px;\n            margin-bottom: 20px;\n            border: 1px solid var(--accent-danger);\n            color: var(--accent-danger);\n            background: rgba(248, 81, 73, 0.1);\n        }\n        h1 { font-size: 24px; margin-bottom: 12px; color: #f0f6fc; }\n        p { font-size: 14px; color: var(--text-secondary); line-height: 1.6; margin-bottom: 24px; }\n        .footer { font-size: 12px; color: var(--text-secondary); border-top: 1px solid var(--border-color); padding-top: 16px; }\n    </style>\n</head>\n<body>\n    <div class=\"card\">\n        <div class=\"status-badge\">HTTP {{.Status}}</div>\n        <h1>{{.Title}}</h1>\n        <p>{{.Message}}</p>\n        <div class=\"footer\">OpenClaw Secure File Transport</div>\n    </div>\n</body>\n</html>\n";
export const DEFAULT_UPLOAD_HTML = BUILTIN_UPLOAD_HTML;
export const DEFAULT_ERROR_HTML = BUILTIN_ERROR_HTML;
